int run(int argc,wchar_t** argv){check(argc==2,"oracle path");std::ifstream in(std::filesystem::path(argv[1]),std::ios::binary);std::string s{std::istreambuf_iterator<char>(in),{}};auto oracle=JsonObject::Parse(winrt::to_hstring(s));auto rows=oracle.GetNamedArray(L"cases");check(rows.Size()==4732,"oracle coverage");unsigned linked=0;for(unsigned i=0;i<rows.Size();++i){auto row=rows.GetObjectAt(i);context=winrt::to_string(row.GetNamedString(L"name"));RasterHistoryFixture::run(row);if(i%79==0){RasterHistoryFixture::run(row,true);++linked;}}context="edges";RasterHistoryFixture::edges(rows.GetObjectAt(0));std::cout<<rows.Size()<<" actual legacy indexed outline results/history, "<<linked<<" linked variants, preview/cancel/direct/worker, three encoders and transaction checks passed\n";return 0;}
